import axios from "axios";

// 🔹 Base API setup
const API = axios.create({
  baseURL: "http://localhost:5000/api",
});

// 🔹 Attach JWT token automatically
API.interceptors.request.use((req) => {
  const token = localStorage.getItem("token");
  if (token) req.headers.Authorization = `Bearer ${token}`;
  return req;
});

// AUTH
export const register = (data) => API.post("/auth/register", data);
export const login = (data) => API.post("/auth/login", data);

// PRODUCTS
export const getProducts = () => API.get("/products");

// CART (User-based)
export const getCart = async () => {
  const user = JSON.parse(localStorage.getItem("user"));
  if (!user) throw new Error("User not logged in");
  return API.get(`/cart/${user._id}`);
};

export const addToCart = async (productId, qty = 1) => {
  const user = JSON.parse(localStorage.getItem("user"));
  if (!user) throw new Error("User not logged in");

  return API.post("/cart", { userId: user._id, productId, qty });
};

// <-- NEW: updateQty
export const updateQty = (cartItemId, qty) => {
  // qty should be a number
  return API.patch(`/cart/${cartItemId}`, { qty });
};

export const removeFromCart = (id) => API.delete(`/cart/${id}`);

export const clearCart = async () => {
  const user = JSON.parse(localStorage.getItem("user"));
  if (!user) throw new Error("User not logged in");
  return API.delete(`/cart/clear/${user._id}`);
};

// CHECKOUT
export const checkout = async (cartItems) => {
  const user = JSON.parse(localStorage.getItem("user"));
  if (!user) throw new Error("User not logged in");

  return API.post("/checkout", { userId: user._id, cartItems });
};

export const confirmPayment = async (orderId) => {
  const user = JSON.parse(localStorage.getItem("user"));
  if (!user) throw new Error("User not logged in");

  await API.delete(`/cart/clear/${user._id}`);
  return { message: "Payment confirmed and cart cleared." };
};
